// Catatan.java
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public class Catatan {
    public static void tulis(String berkas, List<String> baris) throws IOException {
        Files.write(Paths.get(berkas), baris);
    }

    public static List<String> baca(String berkas) throws IOException {
        if (!Files.exists(Paths.get(berkas))) {
            return new ArrayList<>();
        }
        return Files.readAllLines(Paths.get(berkas));
    }

    public static void tambah(String berkas, String baris) throws IOException {
        List<String> isi = new ArrayList<>(baca(berkas));
        isi.add(baris);
        tulis(berkas, isi);
    }
}

