// NilaiCsv.java
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;

public class NilaiCsv {
    public static double rataRata(String berkas) throws IOException {
        int jumlah = 0;
        int banyak = 0;
        for (String baris : Files.readAllLines(Paths.get(berkas))) {
            String[] bagian = baris.split(",");
            if (bagian.length < 2) {
                continue;
            }
            try {
                jumlah += Integer.parseInt(bagian[1].trim());
                banyak++;
            } catch (NumberFormatException e) {
                // baris rusak dilewati
            }
        }
        return banyak == 0 ? 0 : (double) jumlah / banyak;
    }

    public static String tertinggi(String berkas) throws IOException {
        String nama = "-";
        int terbaik = Integer.MIN_VALUE;
        for (String baris : Files.readAllLines(Paths.get(berkas))) {
            String[] bagian = baris.split(",");
            if (bagian.length < 2) {
                continue;
            }
            try {
                int nilai = Integer.parseInt(bagian[1].trim());
                if (nilai > terbaik) {
                    terbaik = nilai;
                    nama = bagian[0].trim();
                }
            } catch (NumberFormatException e) {
                // baris rusak dilewati
            }
        }
        return nama;
    }
}

